import{_ as o,o as d,c,a2 as a}from"./chunks/framework.Cw6yz976.js";const g=JSON.parse('{"title":"更新日志","description":"","frontmatter":{},"headers":[],"relativePath":"guide/changelog.md","filePath":"guide/changelog.md","lastUpdated":1790349375000}'),t={name:"guide/changelog.md"};function i(l,e,r,s,n,h){return d(),c("div",null,[...e[0]||(e[0]=[a('<h1 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h1><p><a href="./CHANGELOG">English</a> | <a href="./CHANGELOG.zh-CN">中文</a></p><h2 id="_1-6-0" tabindex="-1">1.6.0 <a class="header-anchor" href="#_1-6-0" aria-label="Permalink to &quot;1.6.0&quot;">​</a></h2><h3 id="新增" tabindex="-1">新增 <a class="header-anchor" href="#新增" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li><strong><code>#http_server(port; &quot;handler&quot;)</code></strong> —— 阻塞式 HTTP 服务（原生 socket，零依赖）。每个请求构造 <code>req = {method; path; headers; body}</code> 并按名调用 handler；handler 返回字符串（200）或 <code>{code; body; type}</code> 完全控制</li><li><strong>时间内置</strong>：<code>#date_format(ts; fmt)</code> 格式化任意 unix 时间戳（默认 <code>%Y-%m-%d %H:%M:%S</code>）；<code>#parse_time(s; fmt)</code> 把格式化字符串解析回时间戳（<code>%Y %m %d %H %M %S</code> 子集，容忍分隔符）</li><li><strong><code>#uuid()</code></strong> —— 随机 UUID v4（36 字符，RFC-4122 版本/变体位）</li><li><strong>文件内置</strong>：<code>#file_time(path)</code> 返回文件最后修改时间（unix 秒）；<code>#truncate(path; size)</code> 将文件截断 / 扩展为指定字节数</li><li><strong><code>#arch()</code></strong> —— <code>&quot;x64&quot;</code> / <code>&quot;arm64&quot;</code> / <code>&quot;x86&quot;</code> / <code>&quot;unknown&quot;</code>（运行时平台名自 0.4 起为 <code>#platform()</code>）</li><li>语法高亮扩展至全部 183 个内置</li></ul><h2 id="_1-5-0" tabindex="-1">1.5.0 <a class="header-anchor" href="#_1-5-0" aria-label="Permalink to &quot;1.5.0&quot;">​</a></h2><h3 id="新增-1" tabindex="-1">新增 <a class="header-anchor" href="#新增-1" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li><strong>vpm publish</strong>：<code>vesna --pkg publish</code> —— 一键发布包：校验 <code>vesna-pkg.json</code>、将 <code>entry</code> + 元数据打包为 <code>&lt;name&gt;-&lt;version&gt;.zip</code>（Windows 用 PowerShell <code>Compress-Archive</code>，其他平台用 <code>zip</code>）、计算 zip <code>sha256</code>、写入 <code>registry-entry.json</code>，若存在本地 <code>registry.json</code> 则自动追加条目</li><li><strong><code>#call(fname; arg...)</code> 内置</strong>（dispatch 176）：按函数名字符串动态调用 —— 支撑包级框架（如新的 <code>vesna-test</code> 测试框架）</li><li><strong><code>vesna-test</code> 包 1.0.0</strong>：单元测试框架（<code>test_case(name; &quot;fn&quot;)</code>、<code>test_run()</code>、<code>test_eq</code>、<code>test_assert</code>、<code>test_true</code>、<code>test_count</code>）—— 已发布到 vesna-pkg registry</li><li><strong>import 支持包的 <code>entry</code> 字段</strong>：<code>import</code> 现在会读取 vpm 包 <code>vesna-pkg.json</code> 的 <code>entry</code>（此前只尝试 <code>&lt;包名&gt;.ves</code>）；导入包的全局环境通过 parent 链可查看到调用方脚本的函数</li><li><strong><code>vesna --fmt &lt;file&gt;</code></strong>：源码格式化器 —— 规范化缩进（<code>-</code> 层数）、去除行尾空白、压缩连续空行（纯行级，不改语法）</li><li><strong>语法高亮 1.1-1.4</strong>：<code>vesna.tmLanguage.json</code> 内置模式扩展至全部 176 个内置（thread/lock/http/bin/json/crypto/proc/ffi/csv/ini/xml/call）</li><li><strong>REPL Tab 补全</strong>（Windows）：输入 <code>#js&lt;Tab&gt;</code> 等 —— 唯一匹配自动补全，多匹配列出候选</li></ul><h2 id="_1-4-0" tabindex="-1">1.4.0 <a class="header-anchor" href="#_1-4-0" aria-label="Permalink to &quot;1.4.0&quot;">​</a></h2><h3 id="新增-2" tabindex="-1">新增 <a class="header-anchor" href="#新增-2" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li><strong>原生 C++ LSP</strong>：<code>vesna.exe --lsp</code> —— 内置语言服务器（stdio JSON-RPC），诊断复用 C++ <code>Parser</code> 错误收集；补全覆盖全部内置（单一名字表 + 文档标识符，<code>#</code> 触发）；悬停（内置/关键字文档 + 函数定义）；<code>documentSymbol</code>（函数）；<code>foldingRange</code>（缩进块）</li><li><strong>VSCode 插件 0.5.0</strong>：<code>vesna-0.5.0.vsix</code> —— 服务器改为启动 <code>vesna --lsp</code>（不再依赖 Python）；Python LSP 服务器目录已移除</li><li><strong>第四梯队内置</strong>（dispatch 170-175）：<code>#csv_parse(s)</code> → 行列列表；<code>#csv_build(rows)</code> → CSV 文本（RFC-4180 引号）；<code>#ini_read(path)</code> / <code>#ini_write(path; data)</code>（节/键/值，<code>;</code> <code>#</code> 注释）；<code>#xml_parse(s)</code> → 简易 DOM <code>{tag; attrs; children; text}</code>（属性、嵌套、自闭合、<code>&amp;amp;</code> <code>&amp;lt;</code> <code>&amp;gt;</code> <code>&amp;quot;</code> <code>&amp;apos;</code>）；<code>#ffi_call_s(dll; func; arg...)</code> → <code>char*</code> 结果转为字符串</li><li><strong>CI 修复</strong>：编译补 <code>-lws2_32</code>（1.1 网络内置）；golden 回归扩展 tier3 / binary / tier4；concurrency 运行检查；vpm 校验冒烟；LSP 冒烟直接驱动编译出的 <code>vesna.exe --lsp</code>；<code>release.yml</code> 对齐 1.4.0（<code>vesna-0.5.0.vsix</code>、<code>-lws2_32</code>、双语 README/CHANGELOG/CONTRIBUTING + RELEASE-NOTES）</li><li><strong>内置单源事实</strong>：175 项名字表 <code>g_builtinNames</code> 同时驱动词法内置集合、分发表与 LSP 补全（此前是三份手工维护的表）</li></ul><h2 id="_1-3-1" tabindex="-1">1.3.1 <a class="header-anchor" href="#_1-3-1" aria-label="Permalink to &quot;1.3.1&quot;">​</a></h2><h3 id="修复" tabindex="-1">修复 <a class="header-anchor" href="#修复" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li><code>--install</code> 现在支持在发布包的 <code>bin\\</code> 目录内直接运行（安装程序会自动识别当前目录末尾的 <code>\\bin</code> 并上溯到包根目录）。此前会报「找不到 bin\\vesna.exe」。</li></ul><h2 id="_1-3-0-1-3-0" tabindex="-1">1.3.0## 1.3.0 <a class="header-anchor" href="#_1-3-0-1-3-0" aria-label="Permalink to &quot;1.3.0## 1.3.0&quot;">​</a></h2><h3 id="新增-3" tabindex="-1">新增 <a class="header-anchor" href="#新增-3" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li><strong>vpm 校验增强</strong>（<code>lib/pkg.ves</code>）：元数据校验（<code>name</code> 须匹配 <code>^[a-z][a-z0-9_-]+$</code>、<code>version</code> 须为 <code>x.y.z</code>、<code>entry</code> 必须存在）、registry 条目可选 <code>sha256</code> 完整性校验、依赖自动安装（含版本检查与循环保护）、<code>remove</code> 依赖保护（<code>--force</code> 覆盖）。<code>init [名称]</code> 现在校验包名。</li><li><strong>LSP 0.4.0</strong>（<code>vesna-vscode/server</code>）：解析器同步至冻结的 1.0.0 参考实现（覆盖 0.4 全部语法诊断）；补全覆盖全部 169 个内置（含 1.1/1.2 梯队）；悬停显示内置/关键字文档；<code>documentSymbol</code>（函数）；<code>foldingRange</code>（缩进块）；<code>#</code> 补全触发器。</li><li><strong>VSCode 插件 0.4.0</strong>：<code>vesna-0.4.0.vsix</code>，serverInfo 0.4.0，更新描述。</li></ul><h2 id="_1-2-0-1-2-0" tabindex="-1">1.2.0## 1.2.0 <a class="header-anchor" href="#_1-2-0-1-2-0" aria-label="Permalink to &quot;1.2.0## 1.2.0&quot;">​</a></h2><h3 id="新增-4" tabindex="-1">新增 <a class="header-anchor" href="#新增-4" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li><strong>数据内置</strong>：<code>#json_encode(v)</code> / <code>#json_decode(s)</code>（原生 JSON，dict 保持插入顺序）、<code>#re_groups(s; pattern)</code>（正则捕获组，未匹配组为 <code>none</code>）</li><li><strong>加密内置</strong>：<code>#sha256(s)</code>（已按 FIPS 180-4 向量验证）、<code>#aes_encrypt(data; key)</code> / <code>#aes_decrypt(b64; key)</code>（AES-256-CBC + PKCS7，密钥经 SHA-256 派生，base64 输出，已按 FIPS-197 验证）；新增纯 C++ 的 <code>src/cpp/crypto.h</code> 与 <code>crypto_selftest.cpp</code> 向量校验</li><li><strong>进程内置</strong>：<code>#proc_run(cmd)</code> 返回 <code>{&quot;exit&quot;: 退出码; &quot;output&quot;: stdout}</code></li><li><strong>FFI</strong>：<code>#ffi_call(&quot;dll&quot;; &quot;func&quot;; arg...)</code> —— 从共享库调用 C 函数（Windows x64 用 LoadLibrary/GetProcAddress；Linux/macOS 用 dlopen/dlsym）；参数支持 int / 字符串（<code>char*</code>），最多 6 个，返回 64 位整数结果</li><li>新增冒烟测试 <code>tests/tier3.ves</code>（+ <code>tier3_data.json</code>），golden 由 C++ 生成</li></ul><h2 id="_1-1-0-1-1-0" tabindex="-1">1.1.0## 1.1.0 <a class="header-anchor" href="#_1-1-0-1-1-0" aria-label="Permalink to &quot;1.1.0## 1.1.0&quot;">​</a></h2><h3 id="新增-5" tabindex="-1">新增 <a class="header-anchor" href="#新增-5" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li><strong>并发内置</strong>：<code>#thread(&quot;fn&quot;; arg...)</code>（在新线程中运行函数，全局变量按副本隔离，返回线程 id）、<code>#thread_join(id)</code>（等待并取回 <code>back</code> 值，线程出错则重新抛出）、<code>#thread_count()</code>、<code>#lock(&quot;name&quot;)</code> / <code>#unlock(&quot;name&quot;)</code>（命名互斥锁，用于共享资源保护）；<code>print</code> 输出已互斥，未 join 的线程在退出时自动等待</li><li><strong>网络内置</strong>（需系统 PATH 中有 curl）：<code>#http_get(url)</code>、<code>#http_post(url; body)</code>、<code>#tcp_ping(host; port)</code>（原生 TCP 探测：Windows 用 Winsock，其他平台用 BSD socket）</li><li><strong>二进制内置</strong>：<code>#bin_read(path)</code> / <code>#bin_write(path; bytes)</code>（字节列表）、<code>#bin_hex(bytes)</code> / <code>#bin_unhex(s)</code>、<code>#bin_base64_encode(bytes)</code> / <code>#bin_base64_decode(s)</code> —— 字节即普通整数，可直接套用现有列表操作</li><li>新增冒烟测试 <code>tests/concurrency.ves</code> / <code>tests/binary.ves</code>，golden 由 C++ 生成（冻结的 Python 参考实现不含 1.1 内置）</li></ul><h2 id="_1-0-0-1-0-0" tabindex="-1">1.0.0## 1.0.0 <a class="header-anchor" href="#_1-0-0-1-0-0" aria-label="Permalink to &quot;1.0.0## 1.0.0&quot;">​</a></h2><h3 id="新增-6" tabindex="-1">新增 <a class="header-anchor" href="#新增-6" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li><strong>包管理器（vpm）</strong>：<code>vesna --pkg</code> — init / install（<code>目录</code> | <code>zip</code> | <code>owner:repo</code> | registry 包名）/ remove / list / search / registry；包位于 <code>&lt;VESNA_HOME&gt;\\packages\\&lt;名称&gt;\\&lt;名称&gt;.ves</code>，通过 <code>import &lt;名称&gt;</code> 导入；<code>install &lt;包名&gt;</code> 从缓存的 registry 索引解析包；默认 registry 为 <a href="https://youakasakura-YAS.github.io/vesna-pkg/" target="_blank" rel="noreferrer">Vesna 包花园</a></li><li><strong>调试器</strong>：<code>vesna --debug</code> — 断点（<code>b</code> / <code>del</code>）、继续 / 下一行 / 步入、表达式求值（<code>p</code>）、变量（<code>vars</code>）、调用栈回溯（<code>bt</code>）、源码列表（<code>list</code>）；默认停在第一行</li><li>新内置 <code>#cpdir(src; dst)</code>：递归复制目录</li><li><strong>跨平台</strong>：新增 <code>src/cpp/platform.h</code> 抽象层（UTF-8/16 转换、shell、cwd、chdir、环境变量、临时目录）；CMake 构建支持 Windows / Linux / macOS；注册表内置（<code>-regwrite</code> / <code>-regdelete</code> / <code>-regenv</code>）在非 Windows 平台报&quot;不支持&quot;；<code>#platform</code> 返回 <code>windows</code> / <code>linux</code> / <code>mac</code></li><li>examples golden 基准改为由 C++ 实现生成（权威；Python 参考实现已冻结，仅用于回归）</li><li><strong>通用语言扩充</strong>：新增 70 个内置函数 <ul><li>数学：<code>#sqrt</code> <code>#floor</code> <code>#ceil</code> <code>#exp</code> <code>#log</code> <code>#log10</code> <code>#sin</code> <code>#cos</code> <code>#tan</code> <code>#sign</code> <code>#clamp</code> <code>#rand</code> <code>#randint</code> <code>#choice</code> <code>#shuffle</code></li><li>进制：<code>#hex</code> <code>#bin</code> <code>#oct</code></li><li>字符串：<code>#pad</code> <code>#lpad</code> <code>#rpad</code> <code>#format</code> <code>#hash</code></li><li>列表：<code>#range</code> <code>#first</code> <code>#last</code> <code>#take</code> <code>#drop</code> <code>#set</code> <code>#flatten</code> <code>#zip</code> <code>#insert</code> <code>#remove</code> <code>#index_of</code> <code>#enumerate</code> <code>#concat</code></li><li>字典：<code>#get</code> <code>#items</code> <code>#pop_key</code></li><li>类型判断：<code>#is_str</code> <code>#is_int</code> <code>#is_float</code> <code>#is_bool</code> <code>#is_list</code> <code>#is_dict</code> <code>#is_none</code> <code>#is_group</code></li><li>时间/系统：<code>#now</code> <code>#date</code> <code>#sleep</code> <code>#ticks</code> <code>#platform</code> <code>#temp_dir</code></li><li>文件：<code>#fremove</code> <code>#fmove</code> <code>#fsize</code> <code>#is_dir</code> <code>#is_file</code> <code>#mkdirs</code></li><li>编码：<code>#base64_encode</code> <code>#base64_decode</code> <code>#url_encode</code> <code>#url_decode</code></li><li>函数式：<code>#each</code> <code>#all</code> <code>#any</code> <code>#find_first</code> <code>#sort_by</code></li><li>异常：<code>#throw</code> <code>#assert</code></li></ul></li><li>CI 增加 0.4 内置冒烟测试 golden 对照（<code>tests/smoke04.ves</code>）</li><li>新增内置 <code>#regenv(name)</code>：读取用户环境变量（<code>HKCU\\Environment</code>）</li><li><code>vesna --uninstall</code>：删除安装目录、清理 <code>VESNA_HOME</code>/<code>PATH</code>、删除 <code>.ves</code>/<code>VesnaScript</code> 文件关联</li><li><code>--install</code> 补写 <code>OpenWithProgids</code> 项（此前仅在 <code>install-assoc.reg</code> 中），文件关联完全集成进安装程序</li><li><code>#regdelete</code> 改为递归删除整个键树</li></ul><h3 id="变更" tabindex="-1">变更 <a class="header-anchor" href="#变更" aria-label="Permalink to &quot;变更&quot;">​</a></h3><ul><li>版本号统一为 1.0.0</li><li><code>#format</code> 在 <code>%s</code> <code>%d</code> <code>%f</code> <code>%%</code> 之外支持精度写法（<code>%.2f</code>）</li></ul><h2 id="_0-3-0" tabindex="-1">0.3.0 <a class="header-anchor" href="#_0-3-0" aria-label="Permalink to &quot;0.3.0&quot;">​</a></h2><h3 id="新增-7" tabindex="-1">新增 <a class="header-anchor" href="#新增-7" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li>内置 <code>#regwrite</code>、<code>#regdelete</code>、<code>#shell</code>、<code>#path_clean</code></li><li><code>vesna --install</code> 自动注册文件关联</li><li><code>vesna --version</code>、<code>vesna --help</code></li><li>文件类型图标、右键&quot;用 Vesna 运行&quot;、新建菜单</li><li><strong>C++ 实现</strong>（<code>src/cpp/</code>，静态链接，与 Python 参考实现逐行一致）</li></ul><h3 id="修复-1" tabindex="-1">修复 <a class="header-anchor" href="#修复-1" aria-label="Permalink to &quot;修复&quot;">​</a></h3><ul><li>版本号统一为 0.3.0</li><li>注释解析不再误删字符串内的 <code>/* */</code></li><li><code>if</code>/<code>while</code> 条件支持真值判断（数字 0/空为假，非 0/非空为真）</li><li>文件/注册表/命令类内置出错时抛出可被 <code>try/catch</code> 捕获的错误</li><li>拒绝赋值语句尾部多余内容（此前被静默忽略）</li><li>清理重复的无效代码分支，补充参数边界检查</li></ul><h3 id="变更-1" tabindex="-1">变更 <a class="header-anchor" href="#变更-1" aria-label="Permalink to &quot;变更&quot;">​</a></h3><ul><li>安装程序完全用 Vesna 写</li><li>C++ 版性能优化（grep 10 万行：约 2s → 约 240ms）： <ul><li>正则缓存与字面量快速路径</li><li>变量读取零拷贝（<code>Env::getRef</code>）</li><li><code>Value</code> 判别联合（<code>std::variant</code>，约 104 → 约 40 字节）</li><li>标识符 intern（变量/函数名 → 整数 ID）</li><li>内置函数 if 链 → 哈希分发 + switch</li><li><code>-O3 -flto</code> 编译、关闭 iostream 与 C stdio 同步</li></ul></li></ul><h2 id="_0-2-0" tabindex="-1">0.2.0 <a class="header-anchor" href="#_0-2-0" aria-label="Permalink to &quot;0.2.0&quot;">​</a></h2><h3 id="新增-8" tabindex="-1">新增 <a class="header-anchor" href="#新增-8" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li>字节码 → 暂无，当前是 AST 求值</li><li>内置函数 70+</li><li>标准库：csv、json、text、stat</li><li>工具集：wc、grep、head、tail、sort、uniq、cut、sed、replace、stat、logstat、csv2json、extract</li><li>VSCode 语法高亮 + LSP</li><li>独立 <code>vesna.exe</code></li></ul><h3 id="变更-2" tabindex="-1">变更 <a class="header-anchor" href="#变更-2" aria-label="Permalink to &quot;变更&quot;">​</a></h3><ul><li>内置函数前缀从 <code>-</code> 改为 <code>#</code></li><li><code>elif</code> / <code>else</code> 与 <code>if</code> 同层</li><li><code>-push</code> 改名为 <code>-append</code></li></ul><h2 id="_0-1-0" tabindex="-1">0.1.0 <a class="header-anchor" href="#_0-1-0" aria-label="Permalink to &quot;0.1.0&quot;">​</a></h2><p>初始版本。</p>',42)])])}const p=o(t,[["render",i]]);export{g as __pageData,p as default};
